// src/commands/kpi.ts
import * as fs from "fs";
import pc6 from "picocolors";
import {
  aggregatePrKpis,
  formatPrKpiMarkdown,
  injectKpisIntoPrBody,
  aggregateReleaseKpis,
  writeReleaseKpiReport
} from "@aisdlc/core";
function runKpiPr(options) {
  const baseRef = options.base || "main";
  const headRef = options.head || "HEAD";
  const rootDir = options.root || process.cwd();
  try {
    const kpi = aggregatePrKpis(baseRef, headRef, { cwd: rootDir });
    if (options.json) {
      console.log(JSON.stringify(kpi, null, 2));
      return true;
    }
    const markdown = formatPrKpiMarkdown(kpi);
    if (options.updateFile) {
      if (!fs.existsSync(options.updateFile)) {
        console.error(pc6.red(`
\u2716 [ERROR] Target file '${options.updateFile}' does not exist.
`));
        return false;
      }
      const original = fs.readFileSync(options.updateFile, "utf-8");
      const updated = injectKpisIntoPrBody(original, markdown);
      fs.writeFileSync(options.updateFile, updated, "utf-8");
      console.log(pc6.green(`\u2714 [UPDATED] KPI summary injected into '${options.updateFile}'.`));
    } else {
      console.log("\n" + markdown + "\n");
    }
    return true;
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error(pc6.red(`
\u2716 [ERROR] Failed to calculate PR KPIs: ${msg}
`));
    return false;
  }
}
function runKpiRelease(options) {
  if (!options.release) {
    console.error(pc6.red("\n\u2716 [ERROR] Release branch must be specified (--release <branch>).\n"));
    return false;
  }
  const baseBranch = options.base || "main";
  const rootDir = options.root || process.cwd();
  try {
    console.log(pc6.cyan(`
\u{1F4CA} [AI-SDLC Release KPI] Consolidating metrics for '${pc6.bold(options.release)}'...`));
    const report = aggregateReleaseKpis(options.release, baseBranch, { cwd: rootDir });
    if (options.json) {
      console.log(JSON.stringify(report, null, 2));
      return true;
    }
    const { markdownPath, jsonPath } = writeReleaseKpiReport(report, { outputDir: options.output });
    console.log(pc6.green(`\u2714 [COMPLIANT] Consolidated report successfully generated:`));
    console.log(`  - Markdown: ${pc6.bold(markdownPath)}`);
    console.log(`  - JSON:     ${pc6.bold(jsonPath)}`);
    console.log(`  - KLoC:     ${report.totalKloc} (${report.totalCommits} commits)`);
    console.log(`  - Bugs:     ${report.totalBugs} (Density: ${report.globalDefectDensity} bugs/KLoC)`);
    console.log(`  - Rework:   ${report.reworkTimePercent}% time | ${report.reworkTokensPercent}% tokens
`);
    return true;
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error(pc6.red(`
\u2716 [ERROR] Failed to calculate Release KPIs: ${msg}
`));
    return false;
  }
}

