    console.log(`  Global traceability:   ${pc8.green(String(result.metrics.traceabilityRatio) + "%")}`);
    console.log(`  Maintainability:       ${pc8.bold(String(result.metrics.avgMaintainability) + " / 100")}`);
    console.log(`  Gate verdict:          ${result.metrics.qualityVerdict === "PASS" ? pc8.green("PASS") : pc8.red("FAIL")}`);
    const relPath = path.relative(rootDir, result.outputPath);
