  console.log(`  Average complexity (CC):    ${pc8.bold(String(result.avgCyclomatic))}`);
  console.log(
    `  Code coverage (L/B/F):      ${result.coverage ? pc8.bold(`${result.coverage.linesPct}% / ${result.coverage.branchesPct}% / ${result.coverage.functionsPct}%`) : pc8.dim("N/A (Run test:coverage)")}`
  );
